class Timer:
    def __init__(self):
        self.start_time = None
        self.elapsed_time = 0
        self.running = False

    def start(self):
        if not self.running:
            self.start_time = time.time()
            self.running = True
            print("Timer started.")

    def stop(self):
        if self.running:
            self.elapsed_time += time.time() - self.start_time
            self.running = False
            print(f"Timer stopped. Elapsed time: {self.elapsed_time:.2f} seconds.")

    def reset(self):
        self.start_time = None
        self.elapsed_time = 0
        self.running = False
        print("Timer reset.")

if __name__ == "__main__":
    timer = Timer()
    while True:
        command = input("Enter 'start', 'stop', 'reset', or 'exit': ").strip().lower()
        if command == "start":
            timer.start()
        elif command == "stop":
            timer.stop()
        elif command == "reset":
            timer.reset()
        elif command == "exit":
            break
        else:
            print("Invalid command. Please try again.")
