【写一个计时器，用python，既可以计时又可以随时停下，而且计时的时间自定义】折叠的第 1 步：[已折叠] write_file(path='timer.py'，content='import time
import threading

class Timer:
    def __init__(self, name="Timer"):
        self.name = name
        self.start_time = None
        self.end_time = None
        self.running = False
        self.total_time = 0

    def start(self):
        if not self.running:
            self.start_time = time.time()
            self.running = True
            print(f"{self.name} started at {time.strftime('%Y-%m-%d %H:%M:%S')}")

    def stop(self):
        if self.running:
            self.end_time = time.time()
            self.total_time += self.end_time - self.start_time
            self.running = False
            print(f"{self.name} stopped at {time.strftime('%Y-%m-%d %H:%M:%S')}")

    def reset(self):
        self.total_time = 0
        self.running = False
        print(f"{self.name} reset")

    def get_total_time(self):
        return self.total_time

    def is_running(self):
        return self.running

def main():
    timer = Timer("My Timer")
    print("Enter commands (start, stop, reset, time, exit):")
    while True:
        cmd = input().strip().lower()
        if cmd == "start":
            timer.start()
        elif cmd == "stop":
            timer.stop()
        elif cmd == "reset":
            timer.reset()
        elif cmd == "time":
            print(f"Total time: {timer.get_total_time():.2f} seconds")
        elif cmd == "exit":
            break
        else:
            print("Unknown command")

if __name__ == "__main__":
